from __future__ import annotations

# FINANCEPLUS DESKTOP V1.0
# Single-file distribution. The application source is embedded as a compressed
# payload so this repository copy remains byte-identical to the tested desktop
# build delivered with the Windows installation package.
import base64
import gzip

_PAYLOAD = "[... ELLIPSIZATION ...]"

_SOURCE = gzip.decompress(base64.b64decode(_PAYLOAD))
exec(compile(_SOURCE, __file__, "exec"), globals(), globals())
